nsresult ExchangeFolder::SyncMessages(nsIMsgWindow* window,
                                      nsIUrlListener* urlListener) {
  nsresult rv;
  nsCOMPtr<nsIUrlListener> syncUrlListener = urlListener;
  nsCOMPtr<nsIURI> folderUri;
  rv = FolderUri(this, getter_AddRefs(folderUri));
  NS_ENSURE_SUCCESS(rv, rv);

  auto onSyncStart = [self = RefPtr(this), syncUrlListener, folderUri]() {
    if (syncUrlListener) {
      syncUrlListener->OnStartRunningUrl(folderUri);
    }

    // Format the message we'll show the user while we wait for the remote
    // operation to complete.
    RefPtr<intl::Localization> l10n =
        intl::Localization::Create({"messenger/activityFeedback.ftl"_ns}, true);

    auto l10nArgs = dom::Optional<intl::L10nArgs>();
    l10nArgs.Construct();

    nsCString folderName;
    nsresult rv = self->GetLocalizedName(folderName);
    if (NS_SUCCEEDED(rv)) {
      auto idArg = l10nArgs.Value().Entries().AppendElement();
      idArg->mKey = "folderName"_ns;
      idArg->mValue.SetValue().SetAsUTF8String().Assign(folderName);

      ErrorResult error;
      nsCString message;
      l10n->FormatValueSync("looking-for-messages-folder"_ns, l10nArgs, message,
                            error);

      nsCOMPtr<nsIFeedbackService> feedback =
          mozilla::components::Feedback::Service();
      if (feedback) {
        feedback->ReportStatus(message, "start-meteors"_ns);
      }
    }
  };

  auto onSyncStop = [self = RefPtr(this), syncUrlListener, folderUri](
                        nsresult status, nsTArray<nsMsgKey> const& newKeys,
                        nsTArray<RefPtr<IHeaderBlock>> const& newHeaders) {
    MOZ_ASSERT(newKeys.Length() == newHeaders.Length());

    // Even if the operation failed, there may be some messages to deal with.
    if (!newKeys.IsEmpty()) {
      self->SetHasNewMessages(true);
      self->SetNumNewMessages(static_cast<int32_t>(newKeys.Length()));
      self->SetBiffState(nsIMsgFolder::nsMsgBiffState_NewMail);

      // Do the filters require full message body?
      // If they do, then we won't need to keep the headers around because
      // we'll be stalled until the full message is downloaded, which
      // includes the headers anyway.
      bool incomingFiltersRequireBody = false;
      {
        nsCOMPtr<nsIMsgFilterList> filterList;
        if (NS_SUCCEEDED(
                self->GetFilterList(nullptr, getter_AddRefs(filterList)))) {
          filterList->DoFiltersNeedMessageBody(nsMsgFilterType::Incoming,
                                               &incomingFiltersRequireBody);
        }
      }

      // Queue the messages for filtering.
      for (size_t i = 0; i < newKeys.Length(); ++i) {
        static_cast<void>(self->mFilterQueue.put(
            newKeys[i], incomingFiltersRequireBody ? nullptr : newHeaders[i]));
      }

      // We might be able to apply filtering right away...
      if (!incomingFiltersRequireBody) {
        self->PerformFiltering();
      }

      // Tell the AutoSyncState about the newly-added messages,
      // to queue them for potential offline download.
      self->AutoSyncState()->OnNewHeaderFetchCompleted(newKeys);
    }

    self->NotifyFolderEvent(kFolderLoaded);

    // Tell the caller how things went.
    if (syncUrlListener) {
      syncUrlListener->OnStopRunningUrl(folderUri, status);
    }

    // Clear up the GUI.
    nsCOMPtr<nsIFeedbackService> feedback =
        mozilla::components::Feedback::Service();
    if (feedback) {
      feedback->ReportStatus(""_ns, "stop-meteors"_ns);
    }
  };

  return ExchangePerformMessageSync(this, onSyncStart, onSyncStop);
}
